#!/usr/bin/env bash
# Taskbar & window-switching test (branch ui/taskbar-and-window-switching).
#
# Runs the REAL coordinator twice against an isolated fixture (first-start,
# then normal-start) and verifies the fluxbox files generated by
# 65-taskbar-window-switching.sh: managed blocks exactly once after repeat
# runs, fonts, focus/unfocus contrast, key bindings, and that the earlier
# desktop menu / keys / overlay blocks from 60-fluxbox.sh survive.
#
# Uses the same isolation technique as idempotence-test.sh (private user
# namespace when available; direct run when root, e.g. in a Codespace).
set -e

HERE=$(cd "$(dirname "$BASH_SOURCE[0]")" && pwd)
REPO=$(cd "$HERE/.." && pwd)
WORK=$(mktemp -d /tmp/setup-taskbar.XXXXXX)
trap 'rm -rf "$WORK"' EXIT

fail() { echo "FAIL: $*" >&2; exit 1; }

# --- fixture: fake origin + stubs (same as idempotence-test.sh) ------------
git init -q --bare "$WORK/origin.git"
mkdir -p "$WORK/stub"
for cmd in useradd chown xhost; do
  printf '#!/bin/sh\nexit 0\n' > "$WORK/stub/$cmd"
  chmod +x "$WORK/stub/$cmd"
done
cat > "$WORK/stub/id" <<'EOF'
#!/bin/sh
case " $* " in
  *" roblox"*|*"roblox "*) echo 4242; exit 0;;
  *" steam"*|*"steam "*)  echo 4243; exit 0;;
esac
exec /usr/bin/id "$@"
EOF
chmod +x "$WORK/stub/id"

cp -r "$REPO/.devcontainer" "$WORK/dc"
cp -r "$REPO" "$WORK/repo-src"
rm -rf "$WORK/repo-src/.git"
REPO_SRC="$WORK/repo-src"

# a home that looks used, so we prove user/earlier content survives
H="$WORK/home"
mkdir -p "$H/.fluxbox" "$H/Files/docs"
echo hello > "$H/Files/docs/note.txt"
cat > "$H/.fluxbox/menu" <<'EOF'
[begin] (Fluxbox)
[exec] (Old App) {oldapp}
[end]
EOF
printf 'session.screen0.workspaces: 2\n' > "$H/.fluxbox/init"
printf 'Old User Line\n' > "$H/.fluxbox/keys"

mkdir -p "$WORK/data" "$WORK/bin" "$WORK/xwww-dir"

ISOLATED=0
if unshare -rm true 2>/dev/null; then ISOLATED=1; fi

run_setup() { # run_setup <mode>
  local mode="$1" inner
  inner='
    set -e
    cd "'"$WORK"'/home"
    export HOME="'"$WORK"'/home"
    export PATH="'"$WORK"'/stub:$PATH"
    export GIT_CONFIG_GLOBAL="'"$WORK"'/gitconfig"
    export DESKTOP_HOME="'"$WORK"'/home"
    export DESKTOP_DATA_DIR="'"$WORK"'/data"
    export DESKTOP_BIN_DIR="'"$WORK"'/bin"
    export DESKTOP_XWWW="'"$WORK"'/xwww-dir/x-www-browser"
    export DESKTOP_REPO_DIR="'"$REPO_SRC"'"
    export DESKTOP_REMOTE_URL="file://'"$WORK"'/origin.git"
    bash "'"$WORK"'/dc/setup.sh" '"${mode:+$mode}"'
  '
  if [ "$ISOLATED" = 1 ]; then
    unshare -rm bash -c 'mount -t tmpfs tmpfs /run; mount -t tmpfs tmpfs /home; '"$inner"
  else
    [ "$(id -u)" = 0 ] || fail "not root and no user namespaces - cannot isolate"
    bash -c "$inner"
  fi
}

echo "== run 1: first-start"
run_setup first-start >/dev/null || fail "first-start run exited non-zero"
echo "== run 2: normal-start (idempotence of the new blocks)"
run_setup normal-start >/dev/null || fail "normal-start run exited non-zero"

FLUX="$WORK/data/private/fluxbox"

# --- managed blocks: exactly once after two runs ---------------------------
count() { grep -c "^# >>> $1 >>>" "$2"; }
[ "$(count taskbar-switch-overlay "$FLUX/overlay")" = 1 ] || fail "overlay block not exactly once"
[ "$(count taskbar-switch-keys "$FLUX/keys")" = 1 ] || fail "keys block not exactly once"
[ "$(count taskbar-switch-init "$FLUX/init")" = 1 ] || fail "init block not exactly once"
[ "$(count taskbar-switch-shortcuts "$FLUX/SHORTCUTS")" = 1 ] || fail "SHORTCUTS block not exactly once"

# --- init additions: iconbar pattern + remote actions -----------------------
grep -q '^session.screen0.iconbar.mode: {static groups} (workspace)$' "$FLUX/init" \
  || fail "iconbar window-pattern mode missing"
grep -q '^session.screen0.allowRemoteActions: true$' "$FLUX/init" \
  || fail "allowRemoteActions missing"
# the init block must come AFTER 60-fluxbox.sh's block (last-wins)
[ "$(grep -n '^# >>> desktop-init >>>' "$FLUX/init" | cut -d: -f1)" \
  -lt "$(grep -n '^# >>> taskbar-switch-init >>>' "$FLUX/init" | cut -d: -f1)" ] \
  || fail "taskbar-switch-init block must follow the desktop-init block"

# --- taskbar readability ----------------------------------------------------
grep -qx '\*.font: sans-10' "$FLUX/overlay" || fail "readable taskbar font missing"

# --- active vs inactive windows visually distinct ---------------------------
grep -q 'window.title.focus.color: rgb:3A/5C/8E' "$FLUX/overlay" || fail "focused titlebar color missing"
grep -q 'window.title.unfocus.color: rgb:1F/1F/2C' "$FLUX/overlay" || fail "unfocused titlebar color missing"
grep -q 'window.label.focus.textColor: rgb:FF/FF/FF' "$FLUX/overlay" || fail "focused label text color missing"
grep -q 'window.label.unfocus.textColor: rgb:8A/8A/A0' "$FLUX/overlay" || fail "unfocused label text color missing"
grep -q 'toolbar.iconbar.focused.color: rgb:3A/5C/8E' "$FLUX/overlay" || fail "focused taskbar button accent missing"
grep -q 'toolbar.iconbar.unfocused' "$FLUX/overlay" || fail "unfocused taskbar button styling missing"

# --- overlay block must come AFTER 60-fluxbox.sh's block (last-wins) --------
[ "$(grep -n '^# >>> desktop-overlay >>>' "$FLUX/overlay" | cut -d: -f1)" \
  -lt "$(grep -n '^# >>> taskbar-switch-overlay >>>' "$FLUX/overlay" | cut -d: -f1)" ] \
  || fail "taskbar overlay block must follow the desktop-overlay block"

# --- keyboard shortcuts (noVNC-safe combos) ---------------------------------
grep -qx 'Control Mod1 Left :PrevWorkspace' "$FLUX/keys" || fail "Ctrl+Alt+Left binding missing"
grep -qx 'Control Mod1 Right :NextWorkspace' "$FLUX/keys" || fail "Ctrl+Alt+Right binding missing"
grep -qx 'Control Mod1 Shift Left :SendToPrevWorkspace' "$FLUX/keys" || fail "Ctrl+Alt+Shift+Left binding missing"
grep -qx 'Control Mod1 Shift Right :SendToNextWorkspace' "$FLUX/keys" || fail "Ctrl+Alt+Shift+Right binding missing"

# --- earlier work preserved (desktop menu, base theme, base keys) ----------
[ "$(count desktop-init "$FLUX/init")" = 1 ] || fail "desktop-init block lost"
[ "$(count desktop-overlay "$FLUX/overlay")" = 1 ] || fail "desktop-overlay block lost"
[ "$(count desktop-keys "$FLUX/keys")" = 1 ] || fail "desktop-keys block lost"
[ "$(count desktop-apps "$FLUX/menu")" = 1 ] || fail "menu managed block lost"
grep -q '\[exec\] (Old App)' "$FLUX/menu" || fail "user menu entries lost"
grep -q 'Old User Line' "$FLUX/keys" || fail "user keys lost"
grep -q 'Mod1 grave :NextWindow' "$FLUX/keys" || fail "Alt+\` window cycling lost"
grep -qx 'Mod1 2 :Workspace 2' "$FLUX/keys" || fail "Alt+2 workspace jump lost"
grep -q '\[exec\] (Keyboard Shortcuts)' "$FLUX/menu" || fail "shortcuts menu entry lost"
grep -q 'Ctrl+Alt+Left / Right' "$FLUX/SHORTCUTS" || fail "shortcut sheet missing new bindings"

echo "PASS: taskbar/window-switching config generated correctly (2 runs, blocks once, earlier work intact)"
